PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX ref: <https://example.com/ref/>
SELECT ?point ?cls ?tsid WHERE {
  ?point brick:hasLocation <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z05> .
  ?point ?cls .
  FILTER (str(?cls) != "http://brickschema.org/schema/1.2/Brick#hasLocation")
  OPTIONAL { ?point ref:hasExternalReference ?ext . ?ext ref:hasTimeseriesId ?tsid . }
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX ref: <https://example.com/ref/>
SELECT ?point ?cls ?tsid WHERE {
  ?point brick:hasLocation <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z05> .
  ?point a ?cls .
  OPTIONAL { ?point ref:hasExternalReference ?ext . ?ext ref:hasTimeseriesId ?tsid . }
}
